package kr.or.arte.seal.retention.persistence;
import kr.or.arte.seal.retention.application.*;import kr.or.arte.seal.retention.domain.RetentionAnchorType;import kr.or.arte.seal.retention.domain.RetentionJobStatus;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Repository public class MyBatisRetentionRepository implements RetentionRepository {private final RetentionMapper mapper;public MyBatisRetentionRepository(RetentionMapper m){mapper=m;}public UUID requestUrgent(UUID id,UUID rights,UUID request,UUID recipient,UUID actor,Instant now){if(mapper.urgent(id,rights,request,recipient,actor,now)==1)return id;return mapper.activeJob(request,actor).orElseThrow(()->new IllegalStateException("파기 작업을 만들 수 없습니다."));}public int scheduleDue(LocalDate today,Instant now){return mapper.scheduleDue(today,now);}public List<RetentionJobSummary> search(UUID a,RetentionJobStatus s){return mapper.search(a,s,100,0);}public Optional<RetentionJobRecord> findScoped(UUID a,UUID id){return mapper.findScoped(a,id);}public Optional<RetentionActorNames> findActorNamesScoped(UUID a,UUID id){return mapper.findActorNamesScoped(a,id);}public Optional<RetentionJobRecord> findScopedForUpdate(UUID a,UUID id){return mapper.findScopedForUpdate(a,id);}public boolean hasActiveHold(UUID r,LocalDate d){return mapper.hasHold(r,d);}public void placeRestrictionHold(UUID id,UUID request,UUID actor,Instant now){if(mapper.restrictionHold(id,request,actor,now)!=1)throw new IllegalStateException("처리제한 보존 보류를 설정할 수 없습니다.");}public void recordAnchor(UUID request,RetentionAnchorType type,LocalDate date,UUID actor,Instant now){if(mapper.recordAnchor(UUID.randomUUID(),request,type,date,actor,now)!=1)throw new NoSuchElementException("동의요청을 찾을 수 없습니다.");}public void placeLegalHold(UUID request,String code,String text,LocalDate expires,UUID actor,Instant now){if(mapper.placeLegalHold(UUID.randomUUID(),request,code,text,expires,actor,now)!=1)throw new IllegalStateException("보존 보류를 설정할 수 없습니다.");}public void releaseLegalHold(UUID hold,UUID actor,Instant now){if(mapper.releaseLegalHold(hold,actor,now)!=1)throw new NoSuchElementException("활성 보존 보류를 찾을 수 없습니다.");}public List<ActiveLegalHoldSummary> activeLegalHolds(UUID actor){return mapper.activeLegalHolds(actor);}public void transition(UUID id,RetentionJobStatus f,RetentionJobStatus t,UUID a,UUID k,RetentionExecutionResult result,Instant n,long v){if(mapper.transition(id,f,t,a,k,result,n,v)!=1)throw new IllegalStateException("파기 작업이 다른 사용자에 의해 변경되었습니다.");}public void event(UUID id,RetentionJobStatus f,RetentionJobStatus t,UUID a,String reason,Instant n){mapper.event(UUID.randomUUID(),id,f,t,a,reason,n);}public List<String> evidencePaths(UUID r){return mapper.evidencePaths(r);}@Transactional public RetentionExecutionResult destroyPrimaryData(UUID job,UUID request,UUID recipient,int files,Instant now){int mail=mapper.destroyMail(request,now);mapper.destroyEvidence(request,now);int sessions=mapper.destroySessions(request,now);int rights=mapper.destroyRights(job,request,now);boolean pii=mapper.destroyRecipient(request,recipient,now)==1;return new RetentionExecutionResult(mail,files,sessions,rights,pii);}public List<RetentionJobSummary> search(UUID actor,RetentionJobStatus status,int limit,int offset){return mapper.search(actor,status,limit,offset);}
public void lockRequest(UUID requestId){if(mapper.lockRequest(requestId)==null)throw new NoSuchElementException("동의요청을 찾을 수 없습니다.");}
public boolean hasStartedDestruction(UUID requestId){return mapper.hasStartedDestruction(requestId);}
public void invalidatePendingEvidence(UUID requestId,Instant now){mapper.invalidatePendingEvidence(requestId,now);}
}
